#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minStartValue(vector<int>& nums) {
        int minVal = 0, sum = 0;
        for (int num : nums) {
            sum += num;
            minVal = min(minVal, sum);
        }
        return 1 - minVal;
    }
};
